//! Exact RCDATA source shares reference decoding and native Text publication.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><textarea id=area>Context</textarea><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://range-rcdata.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
#[test]
fn range_fragment_rcdata_exact_title_textarea_references_and_preprocessing_order(){
 let(mut d,mut f,mut p)=fixture();let controls=f.controls.len();run(&mut d,&mut f,&mut p,r#"
var r=document.createRange(),area=document.getElementById('area'),title=document.createElement('title'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,subtree:true});var raw='\udfff\ud800\r\n&#13;&amp;&NotEqualTilde;&Afr;&#xD800;\0&lt;img id=fake src=missing&gt;&amp;lt;',expected='\udfff\ud800\n\r&\u2242\u0338\ud835\udd04\ufffd\ufffd<img id=fake src=missing>&lt;';for(var context of [title,area]){r.selectNodeContents(context);var fragment=r.createContextualFragment(raw),text=fragment.firstChild;if(fragment.ownerDocument!==document||fragment.childNodes.length!==1||text.nodeType!==3||text.ownerDocument!==document||text.parentNode!==fragment||text.data!==expected||text.data.charCodeAt(0)!==57343||text.data.charCodeAt(1)!==55296||text.data.charCodeAt(2)!==10||text.data.charCodeAt(3)!==13||fragment.isConnected||r.startContainer!==context)throw 'actual exact RCDATA and reference order';}if(title.firstChild!==null||area.value!=='Context'||area.firstChild.data!=='Context'||document.getElementById('fake')!==null||watch.takeRecords().length||document.getElementById('out').textContent!=='Real')throw 'source and native context unchanged';
"#);assert_eq!(f.controls.len(),controls);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn range_fragment_rcdata_author_conversion_uses_live_context_and_preserves_guard(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var r=document.createRange(),area=document.getElementById('area'),out=document.getElementById('out'),calls=0;r.selectNodeContents(out);var source={toString:function(){calls++;r.selectNodeContents(area);return '\udfff&not\ud800in;&amp;';}},fragment=r.createContextualFragment(source);if(calls!==1||fragment.firstChild.data!=='\udfff\u00ac\ud800in;&'||r.startContainer!==area||area.value!=='Context')throw 'live exact RCDATA conversion';var inverse={toString:function(){calls++;r.selectNodeContents(out);return '\ud800&amp;';}};
"#);p.begin_job();assert!(refusal(&mut d,&mut f,&mut p,"r.createContextualFragment(inverse);").contains("not implemented"));p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==2||r.startContainer!==out||out.textContent!=='Real'||area.value!=='Context')throw 'live general markup guard';");
}
#[test]
fn range_fragment_rcdata_native_clone_connection_records_and_text_lifecycle(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var r=document.createRange(),area=document.getElementById('area'),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(area);watch.observe(out,{childList:true});var fragment=r.createContextualFragment('\udfff\ud800&amp;lt;&lt;b&gt;'),text=fragment.firstChild,copy=fragment.cloneNode(true),expected='\udfff\ud800&lt;<b>';if(copy===fragment||copy.firstChild===text||copy.firstChild.data!==expected||copy.ownerDocument!==document)throw 'independent exact RCDATA Text clone';out.appendChild(fragment);var records=watch.takeRecords();if(fragment.firstChild!==null||out.lastChild!==text||text.data!==expected||text.parentNode!==out||!text.isConnected||records.length!==1||records[0].addedNodes[0]!==text||area.value!=='Context')throw 'actual RCDATA Text drain and identity';text.appendData('\ud800');if(text.data!==expected+'\ud800'||copy.firstChild.data!==expected)throw 'native exact character mutation';out.removeChild(text);if(text.parentNode!==null||text.isConnected||text.data!==expected+'\ud800')throw 'native exact RCDATA retirement';
"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn range_fragment_rcdata_owner_general_markup_and_quota_refusal_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var r=document.createRange(),area=document.getElementById('area'),out=document.getElementById('out'),foreign=document.createElementNS('http://www.w3.org/2000/svg','svg'),owner=document.implementation.createHTMLDocument('other'),other=owner.createRange(),watch=new MutationObserver(function(){});other.selectNodeContents(owner.body);watch.observe(document.body,{childList:true,subtree:true});");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let count=f.controls.len();
 for source in ["r.selectNodeContents(out);r.createContextualFragment('\\ud800&amp;');","r.selectNodeContents(foreign);r.createContextualFragment('\\ud800&amp;');","other.createContextualFragment('\\ud800&amp;');"]{p.begin_job();assert!(!refusal(&mut d,&mut f,&mut p,source).is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.len(),count);}
 run(&mut d,&mut f,&mut p,"r.selectNodeContents(area);");let held=p.state.retained_limit;let nodes=p.state.node_limit;let strings=p.state.limits.host.string_bytes;
 for mode in 0..5{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.limits.host.string_bytes=1};let e=refusal(&mut d,&mut f,&mut p,"r.createContextualFragment('\\udfff\\ud800&#13;&NotEqualTilde;&Afr;&amp;');").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.len(),count);p.state.retained_limit=held;p.state.node_limit=nodes;p.state.limits.host.string_bytes=strings;}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||area.value!=='Context'||out.textContent!=='Real')throw 'no exact RCDATA prefix';var fresh=r.createContextualFragment('\\udfff\\ud800&amp;');if(fresh.firstChild.data!=='\\udfff\\ud800&'||fresh.firstChild.ownerDocument!==document)throw 'fresh exact RCDATA recovery';");
}
